 (Optimal Cycle Length) \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u0923: \u0935\u093f\u0938\u094d\u0924\u0943\u0924 \u092a\u094d\u0930\u093e\u092f\u094b\u0917\u093f\u0915 \u0921\u093f\u091c\u093c\u093e\u0907\u0928\n\n\u0907\u0938 \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u093e \u0909\u0926\u094d\u0926\u0947\u0936\u094d\u092f \u091f\u093e\u0907\u092e \u0938\u0940\u0930\u0940\u091c\u093c \u092b\u094b\u0930\u0915\u093e\u0938\u094d\u091f\u093f\u0902\u0917 \u092e\u0949\u0921\u0932 **CycleNet** \u0915\u0947 \u0932\u093f\u090f \u0911\u091f\u094b\u0915\u094b\u0930\u093f\u0932\u0947\u0936\u0928 \u092b\u093c\u0902\u0915\u094d\u0936\u0928 (Autocorrelation Function - ACF) \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0915\u0947 \u0938\u094d\u0935\u091a\u093e\u0932\u093f\u0924 \u0914\u0930 \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u0930\u0942\u092a \u0938\u0947 \u0907\u0937\u094d\u091f\u0924\u092e \u091a\u0915\u094d\u0930 \u0932\u0902\u092c\u093e\u0908 ($S^*$) \u0915\u0940 \u092a\u0939\u091a\u093e\u0928 \u0914\u0930 \u0909\u0938\u0915\u093e \u0905\u0928\u0941\u092d\u0935\u091c\u0928\u094d\u092f \u0938\u0924\u094d\u092f\u093e\u092a\u0928 \u0915\u0930\u0928\u093e \u0939\u0948\u0964\n\n---\n\n## 1. \u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0924\u0930\u094d\u0915 \u0914\u0930 \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e\u090f\u0902 (Rationale & Hypotheses)\n\n### 1.1 \u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0924\u0930\u094d\u0915 (Scientific Rationale)\nCycleNet \u091f\u093e\u0907\u092e \u0938\u0940\u0930\u0940\u091c\u093c \u0921\u0947\u091f\u093e \u0915\u0947 \u091a\u0915\u094d\u0930\u0940\u092f/\u0906\u0935\u0927\u093f\u0915 \u092a\u0948\u091f\u0930\u094d\u0928 (periodic patterns) \u0915\u094b \u0930\u0940\u0915\u0930\u0947\u0902\u091f \u0938\u093e\u0907\u0915\u093f\u0932 \u0930\u093f\u092a\u094d\u0930\u0947\u091c\u0947\u0902\u091f\u0947\u0936\u0928 \u092f\u093e \u0938\u0947\u0917\u092e\u0947\u0902\u091f\u0947\u0936\u0928 \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947 \u092e\u0949\u0921\u0932 \u0915\u0930\u0924\u093e \u0939\u0948\u0964 \u092f\u0926\u093f \u091a\u0915\u094d\u0930 \u0932\u0902\u092c\u093e\u0908 ($S$) \u0917\u0932\u0924 \u091a\u0941\u0928\u0940 \u091c\u093e\u0924\u0940 \u0939\u0948, \u0924\u094b \u091a\u0915\u094d\u0930\u0940\u092f \u0938\u0902\u0930\u0947\u0916\u0923 (cyclical alignment) \u0935\u093f\u0915\u0943\u0924 \u0939\u094b \u091c\u093e\u0924\u093e \u0939\u0948, \u091c\u093f\u0938\u0938\u0947 \u092b\u0947\u091c \u090f\u0930\u0930 (phase errors) \u0909\u0924\u094d\u092a\u0928\u094d\u0928 \u0939\u094b\u0924\u0947 \u0939\u0948\u0902\u0964 \n\u0911\u091f\u094b\u0915\u094b\u0930\u093f\u0932\u0947\u0936\u0928 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u091f\u093e\u0907\u092e \u0938\u0940\u0930\u0940\u091c\u093c \u0915\u0947 \u0938\u094d\u0935\u092f\u0902 \u0915\u0947 \u0932\u0948\u0917\u094d\u0921 \u0938\u0902\u0938\u094d\u0915\u0930\u0923\u094b\u0902 \u0915\u0947 \u0938\u093e\u0925 \u0930\u0948\u0916\u093f\u0915 \u0938\u0902\u092c\u0902\u0927 \u0915\u094b \u092e\u093e\u092a\u0924\u093e \u0939\u0948\u0964 \u0938\u093f\u0917\u094d\u0928\u0932 \u0915\u0947 \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u0905\u0902\u0924\u0930\u094d\u0928\u093f\u0939\u093f\u0924 \u0906\u0935\u0930\u094d\u0924\u0915\u093e\u0932 \u092a\u0930 ACF \u092e\u0947\u0902 \u0938\u094d\u0925\u093e\u0928\u0940\u092f \u0936\u093f\u0916\u0930 (local peaks) \u0928\u093f\u0930\u094d\u092e\u093f\u0924 \u0939\u094b\u0924\u0947 \u0939\u0948\u0902\u0964 \u0905\u0924\u0903 ACF \u092a\u0940\u0915 \u0921\u093f\u091f\u0947\u0915\u094d\u0936\u0928 \u0917\u094d\u0930\u093f\u0921 \u0938\u0930\u094d\u091a \u0915\u0940 \u0909\u091a\u094d\u091a \u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928\u0932 \u0932\u093e\u0917\u0924 \u0915\u0947 \u092c\u093f\u0928\u093e \u0938\u0930\u094d\u0935\u094b\u0924\u094d\u0924\u092e $S^*$ \u0915\u0940 \u092a\u094d\u0930\u0924\u094d\u092f\u0915\u094d\u0937 \u092a\u0939\u091a\u093e\u0928 \u0915\u0930\u0928\u0947 \u0915\u093e \u090f\u0915 \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u0906\u0927\u093e\u0930 \u092a\u094d\u0930\u0926\u093e\u0928 \u0915\u0930\u0924\u093e \u0939\u0948\u0964\n\n### 1.2 \u092a\u094d\u0930\u093e\u092f\u094b\u0917\u093f\u0915 \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e\u090f\u0902 (Hypotheses)\n- **\u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e 1 ($H_1$):** \u0921\u093f\u091f\u094d\u0930\u0947\u0902\u0921 \u0915\u093f\u090f \u0917\u090f \u0921\u0947\u091f\u093e \u092a\u0930 ACF \u0915\u093e \u092a\u094d\u0930\u093e\u0925\u092e\u093f\u0915 \u092a\u094d\u0930\u092e\u0941\u0916 \u0938\u094d\u0925\u093e\u0928\u0940\u092f \u0936\u093f\u0916\u0930 ($S^*$) \u0921\u0947\u091f\u093e \u0915\u0947 \u0905\u0902\u0924\u0930\u094d\u0928\u093f\u0939\u093f\u0924 \u092d\u094c\u0924\u093f\u0915 \u0906\u0935\u0930\u094d\u0924\u0915\u093e\u0932 (\u0909\u0926\u093e. 24 \u0918\u0902\u091f\u0947 \u092f\u093e 168 \u0918\u0902\u091f\u0947) \u0938\u0947 \u0938\u091f\u0940\u0915 \u092e\u0947\u0932 \u0916\u093e\u0924\u093e \u0939\u0948\u0964\n- **\u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e 2 ($H_2$):** ACF-\u0935\u094d\u092f\u0941\u0924\u094d\u092a\u0928\u094d\u0928 \u091a\u0915\u094d\u0930 \u0932\u0902\u092c\u093e\u0908 ($S^*$) \u092a\u0930 \u092a\u094d\u0930\u0936\u093f\u0915\u094d\u0937\u093f\u0924 CycleNet, \u0935\u093f\u091a\u0932\u093f\u0924 \u092f\u093e \u0938\u092c-\u0911\u092a\u094d\u091f\u093f\u092e\u0932 \u091a\u0915\u094d\u0930 \u0932\u0902\u092c\u093e\u0907\u092f\u094b\u0902 ($S^* \\pm \\delta$) \u0914\u0930 \u0921\u093f\u092b\u0949\u0932\u094d\u091f \u092e\u093e\u0928\u094b\u0902 \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u092e\u0947\u0902 \u0915\u093e\u092b\u0940 \u0915\u092e \u092b\u094b\u0930\u0915\u093e\u0938\u094d\u091f\u093f\u0902\u0917 \u090f\u0930\u0930 (MSE/MAE) \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u093f\u0924 \u0915\u0930\u0947\u0917\u093e\u0964\n- **\u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e 3 ($H_3$):** \u092a\u094d\u0930\u093e\u0925\u092e\u093f\u0915 \u092b\u0902\u0921\u093e\u092e\u0947\u0902\u091f\u0932 \u092a\u0940\u0915 ($S^*$), \u0905\u092a\u0928\u0947 \u0939\u093e\u0930\u094d\u092e\u094b\u0928\u093f\u0915\u094d\u0938 ($2S^*, 3S^*$) \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u092e\u0947\u0902 \u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928\u0932 \u0926\u0915\u094d\u0937\u0924\u093e \u0914\u0930 \u0938\u093e\u092e\u093e\u0928\u094d\u092f\u0940\u0915\u0930\u0923 (generalization) \u0915\u093e \u092c\u0947\u0939\u0924\u0930 \u0938\u0902\u0924\u0941\u0932\u0928 \u092a\u094d\u0930\u0926\u093e\u0928 \u0915\u0930\u0947\u0917\u093e\u0964\n\n---\n\n## 2. \u092a\u094d\u0930\u093e\u092f\u094b\u0917\u093f\u0915 \u0938\u0947\u091f\u0905\u092a \u090f\u0935\u0902 \u0921\u0947\u091f\u093e\u0938\u0947\u091f\u094d\u0938 (Experimental Setup & Datasets)\n\n### 2.1 \u0921\u0947\u091f\u093e\u0938\u0947\u091f\u094d\u0938 (Datasets)\n\u0935\u093f\u092d\u093f\u0928\u094d\u0928 \u0906\u0935\u0927\u093f\u0915 \u0935\u093f\u0936\u0947\u0937\u0924\u093e\u0913\u0902 \u0935\u093e\u0932\u0947 \u092e\u093e\u0928\u0915 \u0913\u092a\u0928-\u0938\u094b\u0930\u094d\u0938 \u092b\u094b\u0930\u0915\u093e\u0938\u094d\u091f\u093f\u0902\u0917 \u0921\u0947\u091f\u093e\u0938\u0947\u091f\u094d\u0938:\n1. **Electricity (ECL):** \u092a\u094d\u0930\u0924\u093f \u0918\u0902\u091f\u093e \u0935\u093f\u0926\u094d\u092f\u0941\u0924 \u0916\u092a\u0924 (\u092e\u091c\u092c\u0942\u0924 24-\u0918\u0902\u091f\u0947 \u0914\u0930 168-\u0918\u0902\u091f\u0947 \u0915\u0940 \u0906\u0935\u0927\u093f\u0915\u0924\u093e)\u0964\n2. **Traffic:** \u092a\u094d\u0930\u0924\u093f \u0918\u0902\u091f\u093e \u0938\u0947\u0902\u0938\u0930 \u0921\u0947\u091f\u093e (\u0938\u094d\u092a\u0937\u094d\u091f \u0926\u0948\u0928\u093f\u0915 \u090f\u0935\u0902 \u0938\u093e\u092a\u094d\u0924\u093e\u0939\u093f\u0915 \u091a\u0915\u094d\u0930)\u0964\n3. **Weather:** 10-\u092e\u093f\u0928\u091f \u0905\u0902\u0924\u0930\u093e\u0932 \u092e\u094c\u0938\u092e \u0921\u0947\u091f\u093e (\u0926\u0948\u0928\u093f\u0915 \u0935 \u092c\u0939\u0941-\u0938\u094d\u0924\u0930\u0940\u092f \u092a\u0948\u091f\u0930\u094d\u0928)\u0964\n4. **ETT (ETTh1, ETTm1):** \u091f\u094d\u0930\u093e\u0902\u0938\u092b\u093e\u0930\u094d\u092e\u0930 \u0924\u093e\u092a\u092e\u093e\u0928 \u0921\u0947\u091f\u093e (\u0935\u093f\u092d\u093f\u0928\u094d\u0928 \u0938\u092e\u092f \u092a\u0948\u092e\u093e\u0928\u094b\u0902 \u092a\u0930 \u091a\u0915\u094d\u0930\u0940\u092f\u0924\u093e)\u0964\n\n### 2.2 \u0921\u0947\u091f\u093e \u0935\u093f\u092d\u093e\u091c\u0928 \u090f\u0935\u0902 \u0935\u093f\u0902\u0921\u094b \u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938\n- **\u0935\u093f\u092d\u093e\u091c\u0928 \u0905\u0928\u0941\u092a\u093e\u0924:** \u0915\u093e\u0932\u093e\u0928\u0941\u0915\u094d\u0930\u092e\u093f\u0915 \u0915\u094d\u0930\u092e \u092e\u0947\u0902 70% Train, 10% Validation, \u0914\u0930 20% Test (\u0921\u0947\u091f\u093e \u0932\u0940\u0915\u0947\u091c \u0930\u094b\u0915\u0928\u0947 \u0939\u0947\u0924\u0941 \u092c\u093f\u0928\u093e \u0936\u092b\u0932\u093f\u0902\u0917 \u0915\u0947)\u0964\n- **\u0932\u0941\u0915\u092c\u0948\u0915 \u0935\u093f\u0902\u0921\u094b ($L$):** $L \\in \\{96, 720\\}$\n- **\u092b\u094b\u0930\u0915\u093e\u0938\u094d\u091f\u093f\u0902\u0917 \u0939\u094b\u0930\u093e\u0907\u091c\u0928 ($H$):** $H \\in \\{96, 192, 336, 720\\}$\n\n---\n\n## 3. \u092a\u094d\u0930\u093e\u092f\u094b\u0917\u093f\u0915 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u0914\u0930 \u0924\u0941\u0932\u0928\u093e\u0924\u094d\u092e\u0915 \u0906\u0927\u093e\u0930 (Controls & Baselines)\n\n\u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935\u093f\u0924 \u0935\u093f\u0927\u093f \u0915\u0940 \u092a\u094d\u0930\u092d\u093e\u0935\u0936\u0940\u0932\u0924\u093e \u0915\u0940 \u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0947 \u0932\u093f\u090f \u0928\u093f\u092e\u094d\u0928\u0932\u093f\u0916\u093f\u0924 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u0938\u092e\u0942\u0939 (Controls) \u092a\u0930\u093f\u092d\u093e\u0937\u093f\u0924 \u0915\u093f\u090f \u0917\u090f \u0939\u0948\u0902:\n\n1. **\u0917\u094d\u0930\u093e\u0909\u0902\u0921-\u091f\u094d\u0930\u0941\u0925 \u0921\u094b\u092e\u0947\u0928 \u092c\u0947\u0938\u0932\u093e\u0907\u0928 ($S_{domain}$):** \u0921\u0947\u091f\u093e \u0915\u0940 \u0906\u0935\u0943\u0924\u094d\u0924\u093f \u0906\u0927\u093e\u0930\u093f\u0924 \u0938\u093e\u092e\u093e\u0928\u094d\u092f \u092a\u0942\u0930\u094d\u0935-\u0927\u093e\u0930\u0923\u093e (\u0909\u0926\u093e. Hourly \u0921\u0947\u091f\u093e \u0915\u0947 \u0932\u093f\u090f 24 \u092f\u093e Weekly \u0915\u0947 \u0932\u093f\u090f 168)\u0964\n2. **\u092a\u0930\u094d\u091f\u0930\u094d\u092c\u094d\u0921 / \u0921\u093f\u0938\u094d\u091f\u0949\u0930\u094d\u091f\u0947\u0921 \u0938\u093e\u0907\u0915\u093f\u0932\u094d\u0938 ($S_{perturbed}$):** ACF \u0936\u093f\u0916\u0930 \u0938\u0947 \u091c\u093e\u0928\u092c\u0942\u091d\u0915\u0930 \u0935\u093f\u091a\u0932\u093f\u0924 \u0915\u093f\u090f \u0917\u090f \u092e\u093e\u0928 (\u0909\u0926\u093e. $S^* - 1, S^* + 1, S^* \\pm 5$)\u0964\n3. **\u0939\u093e\u0930\u094d\u092e\u094b\u0928\u093f\u0915 \u0914\u0930 \u0938\u092c-\u0939\u093e\u0930\u094d\u092e\u094b\u0928\u093f\u0915 \u092c\u0947\u0938\u0932\u093e\u0907\u0928:** ACF \u0915\u0947 \u092e\u0932\u094d\u091f\u0940\u092a\u0932\u094d\u0938 ($2S^*$) \u0914\u0930 \u0938\u092c-\u092e\u0932\u094d\u091f\u0940\u092a\u0932\u094d\u0938 ($S^*/2$)\u0964\n4. **\u0905\u0928\u0941\u092d\u0935\u091c\u0928\u094d\u092f \u0917\u094d\u0930\u093f\u0921 \u0938\u0930\u094d\u091a ($S_{grid}$):** \u090f\u0915 \u0935\u093f\u0938\u094d\u0924\u0943\u0924 \u0916\u094b\u091c \u0938\u0940\u092e\u093e ($\\tau \\in [4, 168]$) \u092a\u0930 CycleNet \u0915\u094b \u092a\u094d\u0930\u0936\u093f\u0915\u094d\u0937\u093f\u0924 \u0915\u0930 \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0928\u094d\u092f\u0942\u0928\u0924\u092e \u090f\u0930\u0930 \u0935\u093e\u0932\u093e \u092e\u093e\u0928 (\u0917\u094b\u0932\u094d\u0921 \u0938\u094d\u091f\u0948\u0902\u0921\u0930\u094d\u0921)\u0964\n5. **\u090f\u092c\u094d\u0932\u0947\u0936\u0928 \u092c\u0947\u0938\u0932\u093e\u0907\u0928 ($S=1$ / No-Cycle):** \u0938\u093e\u0907\u0915\u093f\u0932 \u092e\u0948\u0915\u0947\u0928\u093f\u091c\u094d\u092e \u0915\u094b \u0928\u093f\u0937\u094d\u0915\u094d\u0930\u093f\u092f \u0915\u0930 \u092e\u0949\u0921\u0932 \u0915\u093e \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u0928\u0964\n\n### \u092a\u094d\u0930\u0936\u093f\u0915\u094d\u0937\u0923 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 (Training Hyperparameter Controls):\n\u0938\u092d\u0940 \u0924\u0941\u0932\u0928\u093e\u0924\u094d\u092e\u0915 \u092e\u0949\u0921\u0932\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u090f\u0915 \u0938\u092e\u093e\u0928 \u0939\u093e\u0907\u092a\u0930\u092a\u0948\u0930\u093e\u092e\u0940\u091f\u0930\u094d\u0938 \u0938\u094d\u0925\u093f\u0930 \u0930\u0916\u0947 \u091c\u093e\u090f\u0902\u0917\u0947:\n- \u0911\u092a\u094d\u091f\u093f\u092e\u093e\u0907\u091c\u093c\u0930: Adam (\u0932\u0930\u094d\u0928\u093f\u0902\u0917 \u0930\u0947\u091f: $10^{-4}$)\n- \u092c\u0948\u091a \u0938\u093e\u0907\u091c: 32\n- \u0932\u0949\u0938 \u092b\u0902\u0915\u094d\u0936\u0928: Mean Squared Error (MSE)\n- \u0930\u0948\u0902\u0921\u092e \u0938\u0940\u0921\u094d\u0938: 5 \u0905\u0932\u0917-\u0905\u0932\u0917 \u0938\u0940\u0921\u094d\u0938 (\u0909\u0926\u093e. 42, 123, 456, 789, 2024) \u092a\u0930 \u0926\u094b\u0939\u0930\u093e\u0935\u0964\n\n---\n\n## 4. \u0935\u093f\u0938\u094d\u0924\u0943\u0924 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u092f\u094b\u091c\u0928\u093e (Detailed Analysis Plan)\n\n### 4.1 \u092a\u094d\u0930\u0940-\u092a\u094d\u0930\u094b\u0938\u0947\u0938\u093f\u0902\u0917 \u0914\u0930 \u0921\u093f\u091f\u094d\u0930\u0947\u0902\u0921\u093f\u0902\u0917\n\u0928\u0949\u0928-\u0938\u094d\u091f\u0947\u0936\u0928\u0930\u0940 \u091f\u094d\u0930\u0947\u0902\u0921\u094d\u0938 \u0915\u0947 \u0915\u093e\u0930\u0923 ACF \u0915\u093e \u0917\u0932\u0924 \u092c\u0939\u093e\u0935 \u0930\u094b\u0915\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092e\u0942\u0935\u093f\u0902\u0917 \u090f\u0935\u0930\u0947\u091c \u092f\u093e \u0930\u093f\u0935\u0930\u094d\u0938\u0947\u092c\u0932 \u0928\u0949\u0930\u094d\u092e\u0932\u093e\u0907\u091c\u0947\u0936\u0928 (RevIN) \u0926\u094d\u0935\u093e\u0930\u093e \u0938\u0940\u0930\u0940\u091c\u093c \u0915\u094b \u0921\u093f\u091f\u094d\u0930\u0947\u0902\u0921 \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948:\n$$x'_t = x_t - \\text{MA}_k(x_t)$$\n\n### 4.2 ACF \u0917\u0923\u0928\u093e (Autocorrelation Calculation)\n\u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u091a\u0948\u0928\u0932 $c$ \u0915\u0947 \u0932\u093f\u090f Wiener-Khinchin \u092a\u094d\u0930\u092e\u0947\u092f \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0915\u0947 FFT \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947 \u092b\u093e\u0938\u094d\u091f \u0911\u091f\u094b\u0915\u094b\u0930\u093f\u0932\u0947\u0936\u0928 \u0915\u0940 \u0917\u0923\u0928\u093e \u0915\u0940 \u091c\u093e\u0924\u0940 \u0939\u0948:\n$$R_c(\\tau) = \\frac{\\sum_{t=1}^{T-\\tau} (x'_{t,c} - \\bar{x}'_c)(x'_{t+\\tau,c} - \\bar{x}'_c)}{\\sum_{t=1}^T (x'_{t,c} - \\bar{x}'_c)^2}$$\n\u092e\u0932\u094d\u091f\u0940\u0935\u0948\u0930\u093f\u090f\u091f \u091f\u093e\u0907\u092e \u0938\u0940\u0930\u0940\u091c\u093c \u0915\u0947 \u0932\u093f\u090f \u0914\u0938\u0924 ACF \u0928\u093f\u0915\u093e\u0932\u093e \u091c\u093e\u0924\u093e \u0939\u0948:\n$$\\bar{R}(\\tau) = \\frac{1}{C}\\sum_{c=1}^C R_c(\\tau)$$\n\n### 4.3 \u092a\u0940\u0915 \u0921\u093f\u091f\u0947\u0915\u094d\u0936\u0928 \u090f\u0935\u0902 \u091a\u092f\u0928 \u090f\u0932\u094d\u0917\u094b\u0930\u093f\u0926\u092e\n1. **\u0938\u0930\u094d\u091a \u0938\u094d\u092a\u0947\u0938:** $\\tau \\in [\\tau_{\\min}, \\tau_{\\max}]$, \u091c\u0939\u093e\u0901 $\\tau_{\\min} = 4$ \u0914\u0930 $\\tau_{\\max} = \\lfloor L / 2 \\rfloor$ (\u0928\u093e\u0907\u0915\u094d\u0935\u093f\u0938\u094d\u091f/\u0935\u093f\u0902\u0921\u094b \u0938\u0940\u092e\u093e)\u0964\n2. **\u0938\u094d\u0925\u093e\u0928\u0940\u092f \u0936\u093f\u0916\u0930 \u0938\u094d\u0925\u093f\u0924\u093f:** $\\bar{R}(\\tau) > \\bar{R}(\\tau-1)$ \u0924\u0925\u093e $\\bar{R}(\\tau) > \\bar{R}(\\tau+1)$\u0964\n3. **\u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u092e\u0939\u0924\u094d\u0935 \u092b\u093c\u093f\u0932\u094d\u091f\u0930 (Bartlett's Threshold):**\n   $$\\bar{R}(\\tau) > \\frac{1.96}{\\sqrt{T}}$$\n   (\u091c\u0939\u093e\u0901 $T$ \u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917 \u0938\u0948\u0902\u092a\u0932\u094d\u0938 \u0915\u0940 \u0915\u0941\u0932 \u0938\u0902\u0916\u094d\u092f\u093e \u0939\u0948)\u0964\n4. **\u092a\u094d\u0930\u092e\u0941\u0916 \u091a\u0915\u094d\u0930 \u0932\u0902\u092c\u093e\u0908 \u0915\u093e \u091a\u092f\u0928 ($S^*$):** \u092e\u0939\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u0938\u094d\u0925\u093e\u0928\u0940\u092f \u0936\u093f\u0916\u0930\u094b\u0902 \u092e\u0947\u0902 \u0938\u0947 \u0909\u091a\u094d\u091a\u0924\u092e \u0915\u094b\u0930\u093f\u0932\u0947\u0936\u0928 \u092e\u093e\u0928 \u0935\u093e\u0932\u093e \u0932\u0948\u0917:\n   $$S^* = \\arg\\max_{\\tau \\in \\text{Peaks}} \\bar{R}(\\tau)$$\n\n### 4.4 \u0921\u093e\u0909\u0928\u0938\u094d\u091f\u094d\u0930\u0940\u092e \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u090f\u0935\u0902 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0938\u0924\u094d\u092f\u093e\u092a\u0928\n- **\u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938:**\n  $$\\text{MSE} = \\frac{1}{H \\cdot C} \\sum_{i=1}^{H} \\sum_{c=1}^C (y_{t+i, c} - \\hat{y}_{t+i, c})^2$$\n  $$\\text{MAE} = \\frac{1}{H \\cdot C} \\sum_{i=1}^{H} \\sum_{c=1}^C |y_{t+i, c} - \\hat{y}_{t+i, c}|$$\n- **\u0939\u093e\u0907\u092a\u094b\u0925\u093f\u0938\u093f\u0938 \u091f\u0947\u0938\u094d\u091f\u093f\u0902\u0917:** \u0915\u094d\u092f\u093e $S^*$ \u092a\u0930 MSE \u092c\u0947\u0938\u0932\u093e\u0907\u0928\u094d\u0938 ($S_{perturbed}, S_{domain}$) \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u092e\u0947\u0902 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0930\u0942\u092a \u0938\u0947 \u092e\u0939\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u0930\u0942\u092a \u0938\u0947 \u0915\u092e \u0939\u0948? \u0907\u0938\u0915\u0947 \u0932\u093f\u090f \u092a\u0947\u092f\u0930\u094d\u0921 t-\u091f\u0947\u0938\u094d\u091f \u0914\u0930 Wilcoxon Signed-Rank \u091f\u0947\u0938\u094d\u091f ($p < 0.05$) \u0932\u093e\u0917\u0942 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n- **\u0915\u094b\u0930\u093f\u0932\u0947\u0936\u0928 \u0938\u0939\u0938\u0902\u092c\u0902\u0927:** ACF \u092e\u093e\u0928 $R(S)$ \u0914\u0930 \u091f\u0947\u0938\u094d\u091f \u090f\u0930\u0930 \u092e\u0947\u0902 \u0938\u0941\u0927\u093e\u0930 ($\\Delta\\text{MSE}$) \u0915\u0947 \u092c\u0940\u091a Spearman \u0930\u0948\u0902\u0915 \u0915\u094b\u0930\u093f\u0932\u0947\u0936\u0928 \u0915\u0940 \u0917\u0923\u0928\u093e \u0915\u0940 \u091c\u093e\u090f\u0917\u0940\u0964\n\n---\n\n## 5. \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915\u0924\u093e \u090f\u0935\u0902 \u0938\u0940\u092e\u093e\u090f\u0902 (Feasibility & Limitations)\n\n### 5.1 \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915\u0924\u093e (Feasibility)\n- **\u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928\u0932 \u0926\u0915\u094d\u0937\u0924\u093e:** FFT \u0906\u0927\u093e\u0930\u093f\u0924 ACF \u0915\u0940 \u091c\u091f\u093f\u0932\u0924\u093e \u0915\u0947\u0935\u0932 $\\mathcal{O}(T \\log T)$ \u0939\u0948\u0964 \u092f\u0939 \u092a\u0942\u0930\u094d\u0923 \u0917\u094d\u0930\u093f\u0921 \u0938\u0930\u094d\u091a ($\\mathcal{O}(K \\cdot \\text{Training Time})$) \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u092e\u0947\u0902 \u0939\u091c\u093e\u0930\u094b\u0902 \u0917\u0941\u0928\u093e \u0924\u0947\u091c \u0939\u0948 \u0914\u0930 \u0921\u0947\u091f\u093e \u0932\u094b\u0921\u0930 \u092e\u0947\u0902 \u092c\u093f\u0928\u093e \u0915\u093f\u0938\u0940 \u092e\u0939\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u0913\u0935\u0930\u0939\u0947\u0921 \u0915\u0947 \u0930\u0928 \u0939\u094b \u0938\u0915\u0924\u093e \u0939\u0948\u0964\n- **\u0935\u094d\u092f\u093e\u092a\u0915 \u0905\u0928\u0941\u0915\u0942\u0932\u0924\u093e:** \u092f\u0939 \u0935\u093f\u0927\u093f \u0915\u093f\u0938\u0940 \u092d\u0940 \u0921\u094b\u092e\u0947\u0928-\u0935\u093f\u0936\u093f\u0937\u094d\u091f \u091f\u093e\u0907\u092e \u0938\u0940\u0930\u0940\u091c\u093c \u0915\u0947 \u0932\u093f\u090f \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0938\u094d\u0935\u091a\u093e\u0932\u0928\u0940\u092f (automated) \u0939\u0948\u0964\n\n### 5.2 \u0938\u0940\u092e\u093e\u090f\u0902 (Limitations)\n- **\u0938\u092e\u092f-\u092a\u0930\u093f\u0935\u0930\u094d\u0924\u0928\u0936\u0940\u0932 \u091a\u0915\u094d\u0930 (Time-Varying Periodicity):** \u092f\u0926\u093f \u0915\u093f\u0938\u0940 \u0938\u0940\u0930\u0940\u091c\u093c \u092e\u0947\u0902 \u092e\u094c\u0938\u092e\u0940 \u091a\u0915\u094d\u0930 \u0938\u092e\u092f \u0915\u0947 \u0938\u093e\u0925 \u092c\u0926\u0932\u0924\u093e \u0939\u0948 (\u0909\u0926\u093e. \u0928\u0949\u0928-\u0932\u0940\u0928\u093f\u092f\u0930 \u092b\u0947\u091c \u0921\u094d\u0930\u093f\u092b\u094d\u091f), \u0924\u094b \u0938\u094d\u0925\u093f\u0930 ACF \u0914\u0938\u0924 \u091a\u0915\u094d\u0930 \u0932\u0902\u092c\u093e\u0908 \u0915\u094b \u0938\u091f\u0940\u0915 \u0930\u0942\u092a \u0938\u0947 \u0928\u0939\u0940\u0902 \u092a\u0915\u0921\u093c \u0938\u0915\u0924\u093e\u0964\n- **\u092e\u0932\u094d\u091f\u0940\u0935\u0948\u0930\u093f\u090f\u091f \u0935\u093f\u0937\u092e\u0924\u093e (Multivariate Heterogeneity):** \u092f\u0926\u093f \u0905\u0932\u0917-\u0905\u0932\u0917 \u091a\u0948\u0928\u0932\u094b\u0902 \u092e\u0947\u0902 \u092a\u0930\u0938\u094d\u092a\u0930 \u092d\u093f\u0928\u094d\u0928 \u091a\u0915\u094d\u0930 \u0932\u0902\u092c\u093e\u0908\u092f\u093e\u0902 \u0939\u094b\u0902, \u0924\u094b \u090f\u0915 \u0938\u093e\u091d\u093e $\\bar{R}(\\tau)$ \u0938\u092d\u0940 \u0935\u0948\u0930\u093f\u090f\u091f\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u0906\u0926\u0930\u094d\u0936 \u0928\u0939\u0940\u0902 \u0939\u094b \u0938\u0915\u0924\u093e (\u0907\u0938\u0915\u0947 \u0938\u092e\u093e\u0927\u093e\u0928 \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u0924\u093f-\u091a\u0948\u0928\u0932 \u0938\u093e\u0907\u0915\u093f\u0932 \u0930\u093f\u092a\u094d\u0930\u091c\u0947\u0902\u091f\u0947\u0936\u0928 \u0915\u0940 \u0906\u0935\u0936\u094d\u092f\u0915\u0924\u093e \u0939\u094b\u0917\u0940)\u0964\n- **\u0915\u092e\u091c\u094b\u0930 \u0906\u0935\u0927\u093f\u0915\u0924\u093e (Weak Periodicity):** \u0905\u0924\u094d\u092f\u0927\u093f\u0915 \u0936\u094b\u0930 \u092f\u093e \u0917\u0948\u0930-\u0906\u0935\u0927\u093f\u0915 (chaotic/random walk) \u0921\u0947\u091f\u093e \u092e\u0947\u0902 ACF \u0936\u093f\u0916\u0930\u094b\u0902 \u0915\u093e \u092e\u0939\u0924\u094d\u0935 \u0925\u094d\u0930\u0947\u0936\u094b\u0932\u094d\u0921 \u0938\u0947 \u0928\u0940\u091a\u0947 \u0930\u0939 \u0938\u0915\u0924\u093e \u0939\u0948\u0964", "uncertainties": ["\u0915\u094d\u092f\u093e \u0921\u0947\u091f\u093e \u0915\u0947 \u0935\u093f\u092d\u093f\u0928\u094d\u0928 \u091a\u0948\u0928\u0932\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u0905\u0932\u0917-\u0905\u0932\u0917 \u0938\u093e\u0907\u0915\u093f\u0932 \u0932\u0902\u092c\u093e\u0908 \u0915\u093e \u0909\u092a\u092f\u094b\u0917 CycleNet \u0906\u0930\u094d\u0915\u093f\u091f\u0947\u0915\u094d\u091a\u0930 \u0915\u0940 \u091c\u091f\u093f\u0932\u0924\u093e \u0915\u094b \u092c\u0922\u093c\u093e\u090f \u092c\u093f\u0928\u093e \u0938\u0902\u092d\u0935 \u0939\u0948\u0964", "\u0905\u0924\u094d\u092f\u0927\u093f\u0915 \u0932\u0902\u092c\u0940 \u0932\u0941\u0915\u092c\u0948\u0915 \u0935\u093f\u0902\u0921\u094b \u092e\u0947\u0902 \u0909\u091a\u094d\u091a \u0939\u093e\u0930\u094d\u092e\u094b\u0928\u093f\u0915\u094d\u0938 (\u0909\u0926\u093e. 2S, 3S) \u0915\u093e \u092a\u094d\u0930\u093e\u0925\u092e\u093f\u0915 \u091a\u0915\u094d\u0930 \u0932\u0902\u092c\u093e\u0908 S \u092a\u0930 \u0938\u0902\u092d\u093e\u0935\u093f\u0924 \u092a\u094d\u0930\u092d\u093e\u0935\u0964"], "summary": "Complete experiment design for determining optimal CycleNet cycle length via ACF"}", "origin": "completion"}, "llm_response_id": "oPHTaqjSE5_IodAP0b3_sAY", "security_risk": "UNKNOWN", "kind": "ActionEvent", "source_event_index": 13}
